@pytest.mark.parametrize(
    "vector_path", _load_vectors(LENS_VECTORS_DIR), ids=lambda p: p.stem
)
def test_conformance_lens(vector_path: Path, tmp_path: Path) -> None:
    with open(vector_path, encoding="utf-8") as f:
        vector = json.load(f)

    for key in ("name", "description", "input", "expected"):
        assert key in vector, f"Vector {vector_path} missing {key!r}"

    kind = vector["input"]["kind"]
    parent = _build_combine_vertex(tmp_path, kind, vector["input"]["members"])

    rows = vertex_facts(parent, 0.0, float("inf"), kind=kind)
    assert [r["id"] for r in rows] == vector["expected"]["lens_order"]

@settings(max_examples=200, deadline=None)
@given(appends=_appends)
def test_incremental_fold_equals_cold_fold_at_every_position(tmp_path_factory, appends):
    tmp_path = tmp_path_factory.mktemp("inc")
    vpath, store = _scaffold(tmp_path)
    with open_vertex(vpath) as h:
        for kind, ts, key, val in appends:
            _append(store, kind, ts, **{_KEY_FIELD[kind]: key, "value": val})
            batch = h.refresh()
            assert batch is not None
            assert _items(h.snapshot.fold) == _cold(vpath, h.snapshot.position)

def _scan_targets() -> list:
    """Every shipped-prose file this rule judges.

    Derived from the filesystem, never hand-enumerated (docs/RATCHETS.md): a
    hand-written list is a silent pass for every lib, app, and doc added after
    it was written.
    """
    targets: list = []
    for production in ("libs", "apps"):
        base = REPO_ROOT / production
        if not base.is_dir():
            continue
        for package in sorted(base.iterdir()):
            src = package / "src"
            if src.is_dir():
                targets.extend(src.rglob("*.py"))
    for docs_root in ("spec", "docs"):
        base = REPO_ROOT / docs_root
        if base.is_dir():
            targets.extend(base.rglob("*.md"))
    # Conformance generators: their CASE descriptions are copied verbatim into
    # the vectors, which are normative artifacts other implementations read.
    generators = REPO_ROOT / "spec" / "conformance"
    if generators.is_dir():
        targets.extend(sorted(generators.glob("generate_*.py")))
    return [
        p
        for p in sorted(set(targets))
        if "mutants" not in p.parts
        and "__pycache__" not in p.parts
        and ".venv" not in p.parts
    ]
